
-- Seed 18 educational posts across various categories
INSERT INTO public.learn_posts (user_id, title, content, category, media_url, thumbnail_url, media_type, author_name, author_avatar, likes_count, comments_count, shares_count, status, is_featured)
VALUES
  ('00000000-0000-0000-0000-000000000000', 'Understanding Blockchain Technology', 'Blockchain is a distributed ledger technology that enables secure, transparent, and tamper-proof record-keeping. Each block contains a cryptographic hash of the previous block, creating an immutable chain. This technology powers cryptocurrencies like Bitcoin and Ethereum, but its applications extend far beyond digital currencies into supply chain management, healthcare records, and voting systems.', 'Technology', 'https://images.unsplash.com/photo-1639762681485-074b7f938ba0?w=800', 'https://images.unsplash.com/photo-1639762681485-074b7f938ba0?w=400', 'image', 'Dr. Sarah Chen', 'https://images.unsplash.com/photo-1494790108377-be9c29b29330?w=100', 42, 8, 15, 'approved', true),
  
  ('00000000-0000-0000-0000-000000000000', '10 Essential Nutrients for a Healthy Diet', 'A balanced diet requires essential nutrients including Vitamin D, Omega-3 fatty acids, Iron, Calcium, and B12. These nutrients support bone health, brain function, immune response, and energy metabolism. Studies show that 90% of people are deficient in at least one essential nutrient. Incorporating leafy greens, fatty fish, nuts, and fortified foods can help bridge nutritional gaps.', 'Health', 'https://images.unsplash.com/photo-1490645935967-10de6ba17061?w=800', 'https://images.unsplash.com/photo-1490645935967-10de6ba17061?w=400', 'image', 'Dr. Michael Okonkwo', 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d?w=100', 89, 23, 34, 'approved', true),
  
  ('00000000-0000-0000-0000-000000000000', 'Starting a Business with Zero Capital', 'Entrepreneurship does not always require large investments. Service-based businesses, dropshipping, freelancing, and digital products allow you to start with minimal upfront costs. Focus on solving a specific problem, leverage free tools like social media for marketing, and reinvest early profits. Many successful companies started in garages and dorm rooms with nothing but an idea and determination.', 'Business', 'https://images.unsplash.com/photo-1556761175-5973dc0f32e7?w=800', 'https://images.unsplash.com/photo-1556761175-5973dc0f32e7?w=400', 'image', 'James Adeyemi', 'https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=100', 156, 45, 67, 'approved', true),
  
  ('00000000-0000-0000-0000-000000000000', 'Modern Irrigation Techniques for Small Farms', 'Drip irrigation, micro-sprinklers, and smart soil sensors are transforming small-scale agriculture. These technologies reduce water usage by up to 60% while increasing crop yields by 20-30%. Solar-powered irrigation pumps are making these systems accessible to farmers in rural areas. Combined with precision agriculture data, farmers can optimize water delivery to each plant.', 'Agriculture', 'https://images.unsplash.com/photo-1625246333195-78d9c38ad449?w=800', 'https://images.unsplash.com/photo-1625246333195-78d9c38ad449?w=400', 'image', 'Prof. Amina Diallo', 'https://images.unsplash.com/photo-1580489944761-15a19d654956?w=100', 34, 12, 8, 'approved', false),
  
  ('00000000-0000-0000-0000-000000000000', 'Building Your Personal Brand on LinkedIn', 'Your personal brand is your professional identity. Start by optimizing your LinkedIn profile with a compelling headline, professional photo, and keyword-rich summary. Share industry insights 3-4 times per week, engage with others content, and write long-form articles. Consistency and authenticity are key — 70% of hiring managers check candidates social media profiles.', 'Career Development', 'https://images.unsplash.com/photo-1611944212129-29977ae1398c?w=800', 'https://images.unsplash.com/photo-1611944212129-29977ae1398c?w=400', 'image', 'Lisa Thompson', 'https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=100', 201, 56, 89, 'approved', true),
  
  ('00000000-0000-0000-0000-000000000000', 'Introduction to Personal Finance Management', 'The 50/30/20 rule is a simple budgeting framework: allocate 50% of income to needs, 30% to wants, and 20% to savings and debt repayment. Building an emergency fund covering 3-6 months of expenses should be your first priority. Start investing early — even small amounts compound significantly over time. Understanding compound interest is the key to building wealth.', 'Finance', 'https://images.unsplash.com/photo-1554224155-6726b3ff858f?w=800', 'https://images.unsplash.com/photo-1554224155-6726b3ff858f?w=400', 'image', 'Robert Kimani', 'https://images.unsplash.com/photo-1500648767791-00dcc994a43e?w=100', 178, 67, 92, 'approved', false),
  
  ('00000000-0000-0000-0000-000000000000', 'AI and Machine Learning for Beginners', 'Artificial Intelligence is transforming every industry. Machine learning, a subset of AI, enables computers to learn from data without explicit programming. Start with Python and libraries like scikit-learn and TensorFlow. Key concepts include supervised learning, unsupervised learning, and neural networks. The demand for AI skills is projected to grow 40% by 2027.', 'Technology', 'https://images.unsplash.com/photo-1677442136019-21780ecad995?w=800', 'https://images.unsplash.com/photo-1677442136019-21780ecad995?w=400', 'image', 'Dr. Priya Sharma', 'https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=100', 267, 89, 134, 'approved', true),
  
  ('00000000-0000-0000-0000-000000000000', 'Mental Health Awareness: Breaking the Stigma', 'Mental health is just as important as physical health. 1 in 4 people worldwide will experience a mental health condition in their lifetime. Common conditions include anxiety, depression, and burnout. Seeking help is a sign of strength, not weakness. Practice self-care through regular exercise, adequate sleep, mindfulness, and maintaining strong social connections.', 'Health', 'https://images.unsplash.com/photo-1493836512294-502baa1986e2?w=800', 'https://images.unsplash.com/photo-1493836512294-502baa1986e2?w=400', 'image', 'Dr. Grace Nakamura', 'https://images.unsplash.com/photo-1487412720507-e7ab37603c6f?w=100', 312, 98, 156, 'approved', false),
  
  ('00000000-0000-0000-0000-000000000000', 'E-Commerce Strategies for 2025', 'The e-commerce landscape is evolving rapidly. Key trends include social commerce, live shopping events, augmented reality try-ons, and voice commerce. Personalization powered by AI can increase conversion rates by 20%. Focus on mobile-first design, fast loading times, and seamless checkout experiences. Customer retention is 5x cheaper than acquisition.', 'Business', 'https://images.unsplash.com/photo-1556742049-0cfed4f6a45d?w=800', 'https://images.unsplash.com/photo-1556742049-0cfed4f6a45d?w=400', 'image', 'David Osei', 'https://images.unsplash.com/photo-1560250097-0b93528c311a?w=100', 98, 34, 45, 'approved', false),
  
  ('00000000-0000-0000-0000-000000000000', 'Organic Farming: A Complete Guide', 'Organic farming avoids synthetic pesticides and fertilizers, relying instead on crop rotation, composting, biological pest control, and cover crops. While organic yields may be 10-20% lower initially, soil health improves dramatically over 3-5 years. Organic products command 20-100% price premiums. Certification processes vary by country but typically take 2-3 years.', 'Agriculture', 'https://images.unsplash.com/photo-1574943320219-553eb213f72d?w=800', 'https://images.unsplash.com/photo-1574943320219-553eb213f72d?w=400', 'image', 'Fatima Al-Rashid', 'https://images.unsplash.com/photo-1573496359142-b8d87734a5a2?w=100', 67, 21, 19, 'approved', false),
  
  ('00000000-0000-0000-0000-000000000000', 'Resume Writing Tips That Get Interviews', 'Your resume has 6-7 seconds to make an impression. Use action verbs and quantify achievements (e.g., "Increased sales by 35%"). Tailor each resume to the specific job description using relevant keywords. Keep it to 1-2 pages maximum. Include a skills section with both hard and soft skills. A clean, ATS-friendly format dramatically improves your chances.', 'Career Development', 'https://images.unsplash.com/photo-1586281380349-632531db7ed4?w=800', 'https://images.unsplash.com/photo-1586281380349-632531db7ed4?w=400', 'image', 'Caroline Mensah', 'https://images.unsplash.com/photo-1544005313-94ddf0286df2?w=100', 234, 78, 112, 'approved', false),
  
  ('00000000-0000-0000-0000-000000000000', 'Cryptocurrency Investing for Beginners', 'Before investing in cryptocurrency, understand the fundamentals: blockchain technology, market volatility, and different types of tokens. Never invest more than you can afford to lose. Diversify across multiple assets, use dollar-cost averaging, and store your assets in secure wallets. Research thoroughly — read whitepapers, understand the team, and evaluate real-world utility.', 'Finance', 'https://images.unsplash.com/photo-1622630998477-20aa696ecb05?w=800', 'https://images.unsplash.com/photo-1622630998477-20aa696ecb05?w=400', 'image', 'Alex Nwosu', 'https://images.unsplash.com/photo-1506794778202-cad84cf45f1d?w=100', 145, 56, 78, 'approved', false),
  
  ('00000000-0000-0000-0000-000000000000', 'Web Development Roadmap 2025', 'Start with HTML, CSS, and JavaScript fundamentals. Learn a frontend framework like React or Vue.js. For backend, explore Node.js, Python, or Go. Understand databases (SQL and NoSQL), RESTful APIs, and GraphQL. DevOps basics including Docker, CI/CD, and cloud platforms are increasingly important. Build projects, contribute to open source, and never stop learning.', 'Technology', 'https://images.unsplash.com/photo-1461749280684-dccba630e2f6?w=800', 'https://images.unsplash.com/photo-1461749280684-dccba630e2f6?w=400', 'image', 'Mohammed Hassan', 'https://images.unsplash.com/photo-1507591064344-4c6ce005b128?w=100', 189, 67, 95, 'approved', false),
  
  ('00000000-0000-0000-0000-000000000000', 'First Aid Basics Everyone Should Know', 'Knowing basic first aid can save lives. Learn CPR, the Heimlich maneuver, and how to control bleeding. Keep a first aid kit at home and in your car. For burns, run cool water for 10-20 minutes. For fractures, immobilize the area and seek medical help. Always call emergency services for severe injuries. Consider taking a certified first aid course.', 'Health', 'https://images.unsplash.com/photo-1603398938378-e54eab446dde?w=800', 'https://images.unsplash.com/photo-1603398938378-e54eab446dde?w=400', 'image', 'Dr. John Mutua', 'https://images.unsplash.com/photo-1612349317150-e413f6a5b16d?w=100', 156, 34, 67, 'approved', false),
  
  ('00000000-0000-0000-0000-000000000000', 'Supply Chain Management Essentials', 'Effective supply chain management reduces costs by 15-20% and improves customer satisfaction. Key components include demand forecasting, inventory optimization, supplier relationship management, and logistics coordination. Digital transformation through IoT sensors, AI-powered analytics, and blockchain traceability are becoming industry standards.', 'Business', 'https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?w=800', 'https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?w=400', 'image', 'Patricia Agyei', 'https://images.unsplash.com/photo-1551836022-d5d88e9218df?w=100', 56, 19, 23, 'approved', false),
  
  ('00000000-0000-0000-0000-000000000000', 'Greenhouse Farming: Maximizing Year-Round Production', 'Greenhouse farming allows year-round production regardless of climate. Key factors include temperature control, humidity management, light optimization, and pest prevention. Hydroponic and aquaponic systems within greenhouses can increase yields by 10x compared to traditional farming while using 90% less water. ROI typically achieved within 2-3 years.', 'Agriculture', 'https://images.unsplash.com/photo-1416879595882-3373a0480b5b?w=800', 'https://images.unsplash.com/photo-1416879595882-3373a0480b5b?w=400', 'image', 'Dr. Samuel Okafor', 'https://images.unsplash.com/photo-1560250097-0b93528c311a?w=100', 78, 25, 31, 'approved', false),
  
  ('00000000-0000-0000-0000-000000000000', 'Mastering the Art of Negotiation', 'Great negotiators prepare thoroughly, listen actively, and seek win-win outcomes. Use the BATNA framework (Best Alternative to a Negotiated Agreement) to understand your leverage. Never negotiate against yourself. Practice anchoring — the first number mentioned often sets the range. Emotional intelligence and empathy are more powerful than aggressive tactics.', 'Career Development', 'https://images.unsplash.com/photo-1521791136064-7986c2920216?w=800', 'https://images.unsplash.com/photo-1521791136064-7986c2920216?w=400', 'image', 'Victoria Adebayo', 'https://images.unsplash.com/photo-1573497019940-1c28c88b4f3e?w=100', 123, 41, 54, 'approved', false),
  
  ('00000000-0000-0000-0000-000000000000', 'Understanding Insurance: Protecting Your Future', 'Insurance is a financial safety net. Essential types include health, life, auto, and property insurance. Understand terms like premiums, deductibles, copays, and coverage limits. Shop around and compare quotes from multiple providers. Review your policies annually as your needs change. Having adequate insurance prevents financial catastrophe during unexpected events.', 'Finance', 'https://images.unsplash.com/photo-1450101499163-c8848c66ca85?w=800', 'https://images.unsplash.com/photo-1450101499163-c8848c66ca85?w=400', 'image', 'Richard Banda', 'https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?w=100', 67, 22, 18, 'approved', false);
